cd /tmp/orchestra-04/reverify && python3 - <<'EOF'
import ast,sys
tree=ast.parse(open('app.py',encoding='utf-8').read())
mods=set()
for n in ast.walk(tree):
    if isinstance(n,ast.Import):
        for a in n.names: mods.add(a.name.split('.')[0])
    elif isinstance(n,ast.ImportFrom):
        if n.level==0 and n.module: mods.add(n.module.split('.')[0])
print("modules:",sorted(mods))
print("stdlib:",{m:(m in sys.stdlib_module_names) for m in sorted(mods)})
EOF
